import java.io.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = rb();
        while (c != '-' && (c < '0' || c > '9')) c = rb();
        boolean neg = c == '-';
        if (neg) c = rb();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = rb();
        }
        return neg ? -r : r;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        int[] p = new int[n];
        for (int i = 0; i < n; i++) p[i] = (int) nextLong();
        boolean[] seen = new boolean[n];
        int cycles = 0;
        for (int i = 0; i < n; i++) {
            if (seen[i]) continue;
            cycles++;
            for (int j = i; !seen[j]; j = p[j] - 1) seen[j] = true;
        }
        long minimum = n - cycles;
        StringBuilder sb = new StringBuilder(q + 1);
        for (int k = 0; k < q; k++) {
            long v = nextLong();
            sb.append(n > 1 && v >= minimum && (v - minimum) % 2 == 0 ? '1' : '0');
        }
        System.out.println(sb);
    }
}

package main

import (
	"bufio"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	c, _ := reader.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' || c == '\t' {
		c, _ = reader.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = reader.ReadByte()
	}
	n := 0
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = reader.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, q := readInt(), readInt()
	p := make([]int, n)
	for i := range p {
		p[i] = readInt()
	}
	seen := make([]bool, n)
	cycles := 0
	for i := 0; i < n; i++ {
		if seen[i] {
			continue
		}
		cycles++
		for j := i; !seen[j]; j = p[j] - 1 {
			seen[j] = true
		}
	}
	minimum := n - cycles
	out := make([]byte, 0, q+1)
	for k := 0; k < q; k++ {
		v := readInt()
		if n > 1 && v >= minimum && (v-minimum)%2 == 0 {
			out = append(out, '1')
		} else {
			out = append(out, '0')
		}
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
